-- Упражнения книги 19, глава 13 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 13, 'la13-hook-order', 0, 'func', 'Порядок цепочек на хуке', 'text - вывод nft list ruleset. Напишите функцию hook_order(text, hook, version): верните список строк ''семейство таблица цепочка'' для базовых цепочек, привязанных к хуку hook (input, forward, output, prerouting, postrouting) и видящих пакеты IP-версии version (4 или 6), в порядке, в котором их выполняет ядро. Таблица семейства ip относится к версии 4, ip6 - к версии 6, inet - к обеим; таблицы arp, bridge и netdev не подходят никогда. Обычные цепочки (без строки ''type ... hook ...'') пропускайте, строки внутри блоков set, map и flowtable - не правила и не цепочки. Строка ''type T hook H [device D] priority P; policy X;'' задаёт приоритет P: целое число (возможно отрицательное), имя raw -300, mangle -150, dstnat -100, filter 0, security 50, srcnat 100 либо имя со смещением вида ''filter + 10'' или ''srcnat - 5''. Меньшее число выполняется раньше, при равных приоритетах сохраняйте порядок появления в тексте (реальный порядок при равенстве не гарантирован).', 'def hook_order(text, hook, version):
    pass
', 'Разберите текст построчно: table X Y {, chain Z {, строку type ... и блоки set/map; потом sorted(..., key=приоритет) устойчиво сохраняет порядок появления.', '{"func": "hook_order", "tests": [{"args": ["table inet filter {\n\tchain input {\n\t\ttype filter hook input priority filter; policy drop;\n\t\tct state established,related accept\n\t\tct state invalid drop\n\t\tiif \"lo\" accept\n\t\ttcp dport 22 accept\n\t\ttcp dport { 80, 443 } accept\n\t\tip protocol icmp accept\n\t}\n\tchain forward {\n\t\ttype filter hook forward priority filter; policy drop;\n\t}\n\tchain output {\n\t\ttype filter hook output priority filter; policy accept;\n\t}\n}\ntable ip nat {\n\tchain prerouting {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\ttcp dport 8080 dnat to 10.0.0.5:80\n\t}\n\tchain postrouting {\n\t\ttype nat hook postrouting priority srcnat; policy accept;\n\t\toifname \"eth0\" masquerade\n\t}\n}\n", "input", 4], "expected": ["inet filter input"]}, {"args": ["table inet filter {\n\tchain input {\n\t\ttype filter hook input priority filter; policy drop;\n\t\tct state established,related accept\n\t\tct state invalid drop\n\t\tiif \"lo\" accept\n\t\ttcp dport 22 accept\n\t\ttcp dport { 80, 443 } accept\n\t\tip protocol icmp accept\n\t}\n\tchain forward {\n\t\ttype filter hook forward priority filter; policy drop;\n\t}\n\tchain output {\n\t\ttype filter hook output priority filter; policy accept;\n\t}\n}\ntable ip nat {\n\tchain prerouting {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\ttcp dport 8080 dnat to 10.0.0.5:80\n\t}\n\tchain postrouting {\n\t\ttype nat hook postrouting priority srcnat; policy accept;\n\t\toifname \"eth0\" masquerade\n\t}\n}\n", "prerouting", 4], "expected": ["ip nat prerouting"]}, {"args": ["table inet filter {\n\tchain input {\n\t\ttype filter hook input priority filter; policy drop;\n\t\tct state established,related accept\n\t\tct state invalid drop\n\t\tiif \"lo\" accept\n\t\ttcp dport 22 accept\n\t\ttcp dport { 80, 443 } accept\n\t\tip protocol icmp accept\n\t}\n\tchain forward {\n\t\ttype filter hook forward priority filter; policy drop;\n\t}\n\tchain output {\n\t\ttype filter hook output priority filter; policy accept;\n\t}\n}\ntable ip nat {\n\tchain prerouting {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\ttcp dport 8080 dnat to 10.0.0.5:80\n\t}\n\tchain postrouting {\n\t\ttype nat hook postrouting priority srcnat; policy accept;\n\t\toifname \"eth0\" masquerade\n\t}\n}\n", "postrouting", 6], "expected": []}, {"args": ["table inet firewalld {\n\tchain raw_PREROUTING {\n\t\ttype filter hook prerouting priority raw + 10; policy accept;\n\t\ticmpv6 type nd-router-advert accept\n\t}\n\tchain filter_INPUT {\n\t\ttype filter hook input priority filter + 10; policy accept;\n\t\tct state { established, related } accept\n\t\tjump filter_INPUT_ZONES\n\t}\n\tchain filter_FORWARD {\n\t\ttype filter hook forward priority filter + 10; policy accept;\n\t}\n\tchain filter_INPUT_ZONES {\n\t\ttcp dport 22 accept\n\t}\n\tchain nat_PREROUTING {\n\t\ttype nat hook prerouting priority dstnat + 10; policy accept;\n\t}\n\tchain nat_POSTROUTING {\n\t\ttype nat hook postrouting priority srcnat + 10; policy accept;\n\t}\n}\ntable ip filter {\n\tchain INPUT {\n\t\ttype filter hook input priority filter; policy accept;\n\t\tmeta l4proto tcp tcp dport 3306 counter packets 0 bytes 0 drop\n\t}\n\tchain FORWARD {\n\t\ttype filter hook forward priority filter; policy drop;\n\t}\n}\ntable ip raw {\n\tchain PREROUTING {\n\t\ttype filter hook prerouting priority raw; policy accept;\n\t}\n}\ntable ip6 filter {\n\tchain input {\n\t\ttype filter hook input priority 0; policy drop;\n\t}\n}\ntable inet guard {\n\tchain pre {\n\t\ttype filter hook prerouting priority -300; policy accept;\n\t\tip saddr 192.0.2.66 drop\n\t}\n\tchain in {\n\t\ttype filter hook input priority 0; policy accept;\n\t}\n}\n", "prerouting", 4], "expected": ["ip raw PREROUTING", "inet guard pre", "inet firewalld raw_PREROUTING", "inet firewalld nat_PREROUTING"]}, {"args": ["table inet firewalld {\n\tchain raw_PREROUTING {\n\t\ttype filter hook prerouting priority raw + 10; policy accept;\n\t\ticmpv6 type nd-router-advert accept\n\t}\n\tchain filter_INPUT {\n\t\ttype filter hook input priority filter + 10; policy accept;\n\t\tct state { established, related } accept\n\t\tjump filter_INPUT_ZONES\n\t}\n\tchain filter_FORWARD {\n\t\ttype filter hook forward priority filter + 10; policy accept;\n\t}\n\tchain filter_INPUT_ZONES {\n\t\ttcp dport 22 accept\n\t}\n\tchain nat_PREROUTING {\n\t\ttype nat hook prerouting priority dstnat + 10; policy accept;\n\t}\n\tchain nat_POSTROUTING {\n\t\ttype nat hook postrouting priority srcnat + 10; policy accept;\n\t}\n}\ntable ip filter {\n\tchain INPUT {\n\t\ttype filter hook input priority filter; policy accept;\n\t\tmeta l4proto tcp tcp dport 3306 counter packets 0 bytes 0 drop\n\t}\n\tchain FORWARD {\n\t\ttype filter hook forward priority filter; policy drop;\n\t}\n}\ntable ip raw {\n\tchain PREROUTING {\n\t\ttype filter hook prerouting priority raw; policy accept;\n\t}\n}\ntable ip6 filter {\n\tchain input {\n\t\ttype filter hook input priority 0; policy drop;\n\t}\n}\ntable inet guard {\n\tchain pre {\n\t\ttype filter hook prerouting priority -300; policy accept;\n\t\tip saddr 192.0.2.66 drop\n\t}\n\tchain in {\n\t\ttype filter hook input priority 0; policy accept;\n\t}\n}\n", "input", 4], "expected": ["ip filter INPUT", "inet guard in", "inet firewalld filter_INPUT"]}, {"args": ["table inet firewalld {\n\tchain raw_PREROUTING {\n\t\ttype filter hook prerouting priority raw + 10; policy accept;\n\t\ticmpv6 type nd-router-advert accept\n\t}\n\tchain filter_INPUT {\n\t\ttype filter hook input priority filter + 10; policy accept;\n\t\tct state { established, related } accept\n\t\tjump filter_INPUT_ZONES\n\t}\n\tchain filter_FORWARD {\n\t\ttype filter hook forward priority filter + 10; policy accept;\n\t}\n\tchain filter_INPUT_ZONES {\n\t\ttcp dport 22 accept\n\t}\n\tchain nat_PREROUTING {\n\t\ttype nat hook prerouting priority dstnat + 10; policy accept;\n\t}\n\tchain nat_POSTROUTING {\n\t\ttype nat hook postrouting priority srcnat + 10; policy accept;\n\t}\n}\ntable ip filter {\n\tchain INPUT {\n\t\ttype filter hook input priority filter; policy accept;\n\t\tmeta l4proto tcp tcp dport 3306 counter packets 0 bytes 0 drop\n\t}\n\tchain FORWARD {\n\t\ttype filter hook forward priority filter; policy drop;\n\t}\n}\ntable ip raw {\n\tchain PREROUTING {\n\t\ttype filter hook prerouting priority raw; policy accept;\n\t}\n}\ntable ip6 filter {\n\tchain input {\n\t\ttype filter hook input priority 0; policy drop;\n\t}\n}\ntable inet guard {\n\tchain pre {\n\t\ttype filter hook prerouting priority -300; policy accept;\n\t\tip saddr 192.0.2.66 drop\n\t}\n\tchain in {\n\t\ttype filter hook input priority 0; policy accept;\n\t}\n}\n", "input", 6], "expected": ["ip6 filter input", "inet guard in", "inet firewalld filter_INPUT"]}, {"args": ["table inet firewalld {\n\tchain raw_PREROUTING {\n\t\ttype filter hook prerouting priority raw + 10; policy accept;\n\t\ticmpv6 type nd-router-advert accept\n\t}\n\tchain filter_INPUT {\n\t\ttype filter hook input priority filter + 10; policy accept;\n\t\tct state { established, related } accept\n\t\tjump filter_INPUT_ZONES\n\t}\n\tchain filter_FORWARD {\n\t\ttype filter hook forward priority filter + 10; policy accept;\n\t}\n\tchain filter_INPUT_ZONES {\n\t\ttcp dport 22 accept\n\t}\n\tchain nat_PREROUTING {\n\t\ttype nat hook prerouting priority dstnat + 10; policy accept;\n\t}\n\tchain nat_POSTROUTING {\n\t\ttype nat hook postrouting priority srcnat + 10; policy accept;\n\t}\n}\ntable ip filter {\n\tchain INPUT {\n\t\ttype filter hook input priority filter; policy accept;\n\t\tmeta l4proto tcp tcp dport 3306 counter packets 0 bytes 0 drop\n\t}\n\tchain FORWARD {\n\t\ttype filter hook forward priority filter; policy drop;\n\t}\n}\ntable ip raw {\n\tchain PREROUTING {\n\t\ttype filter hook prerouting priority raw; policy accept;\n\t}\n}\ntable ip6 filter {\n\tchain input {\n\t\ttype filter hook input priority 0; policy drop;\n\t}\n}\ntable inet guard {\n\tchain pre {\n\t\ttype filter hook prerouting priority -300; policy accept;\n\t\tip saddr 192.0.2.66 drop\n\t}\n\tchain in {\n\t\ttype filter hook input priority 0; policy accept;\n\t}\n}\n", "forward", 4], "expected": ["ip filter FORWARD", "inet firewalld filter_FORWARD"]}, {"args": ["table inet filter {\n\tset blocklist {\n\t\ttype ipv4_addr\n\t\tflags interval\n\t\telements = { 192.0.2.0/24, 198.51.100.7 }\n\t}\n\tmap svc {\n\t\ttype inet_service : verdict\n\t\telements = { 22 : accept }\n\t}\n\tchain input {\n\t\ttype filter hook input priority 0; policy accept;\n\t\tip saddr @blocklist drop\n\t}\n}\ntable bridge br {\n\tchain forward {\n\t\ttype filter hook forward priority -200; policy accept;\n\t}\n}\ntable netdev early {\n\tchain ingress {\n\t\ttype filter hook ingress device \"eth0\" priority -500; policy accept;\n\t}\n}\ntable inet pair {\n\tchain a {\n\t\ttype filter hook input priority 10; policy accept;\n\t}\n\tchain b {\n\t\ttype filter hook input priority 10; policy drop;\n\t}\n\tchain c {\n\t\ttype filter hook input priority -10; policy accept;\n\t}\n\tchain helper {\n\t\taccept\n\t}\n}\n", "input", 4], "expected": ["inet pair c", "inet filter input", "inet pair a", "inet pair b"]}, {"args": ["table inet filter {\n\tset blocklist {\n\t\ttype ipv4_addr\n\t\tflags interval\n\t\telements = { 192.0.2.0/24, 198.51.100.7 }\n\t}\n\tmap svc {\n\t\ttype inet_service : verdict\n\t\telements = { 22 : accept }\n\t}\n\tchain input {\n\t\ttype filter hook input priority 0; policy accept;\n\t\tip saddr @blocklist drop\n\t}\n}\ntable bridge br {\n\tchain forward {\n\t\ttype filter hook forward priority -200; policy accept;\n\t}\n}\ntable netdev early {\n\tchain ingress {\n\t\ttype filter hook ingress device \"eth0\" priority -500; policy accept;\n\t}\n}\ntable inet pair {\n\tchain a {\n\t\ttype filter hook input priority 10; policy accept;\n\t}\n\tchain b {\n\t\ttype filter hook input priority 10; policy drop;\n\t}\n\tchain c {\n\t\ttype filter hook input priority -10; policy accept;\n\t}\n\tchain helper {\n\t\taccept\n\t}\n}\n", "forward", 4], "expected": []}, {"args": ["table inet filter {\n\tset blocklist {\n\t\ttype ipv4_addr\n\t\tflags interval\n\t\telements = { 192.0.2.0/24, 198.51.100.7 }\n\t}\n\tmap svc {\n\t\ttype inet_service : verdict\n\t\telements = { 22 : accept }\n\t}\n\tchain input {\n\t\ttype filter hook input priority 0; policy accept;\n\t\tip saddr @blocklist drop\n\t}\n}\ntable bridge br {\n\tchain forward {\n\t\ttype filter hook forward priority -200; policy accept;\n\t}\n}\ntable netdev early {\n\tchain ingress {\n\t\ttype filter hook ingress device \"eth0\" priority -500; policy accept;\n\t}\n}\ntable inet pair {\n\tchain a {\n\t\ttype filter hook input priority 10; policy accept;\n\t}\n\tchain b {\n\t\ttype filter hook input priority 10; policy drop;\n\t}\n\tchain c {\n\t\ttype filter hook input priority -10; policy accept;\n\t}\n\tchain helper {\n\t\taccept\n\t}\n}\n", "ingress", 4], "expected": []}, {"args": ["", "input", 4], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 13, 'la13-verdict', 1, 'func', 'Вердикт для пакета', 'text - вывод nft list ruleset, hook - имя хука, pkt - словарь пакета IPv4 с ключами iif, proto (tcp, udp или icmp), saddr, daddr, sport, dport (для icmp None) и ct (new, established, related, invalid). Напишите функцию packet_verdict(text, hook, pkt): верните ''accept'', ''drop'' или ''reject''. Учитываются только базовые цепочки типа filter на хуке hook в таблицах семейств ip и inet, в порядке возрастания приоритета (имена как в nft: raw -300, mangle -150, dstnat -100, filter 0, security 50, srcnat 100, возможно со смещением ''filter + 10''; при равенстве - порядок появления). Каждая цепочка даёт результат: drop или reject из неё окончательны для всего пакета; accept заканчивает только эту цепочку, и пакет идёт в следующую; если цепочка закончилась без вердикта (или сработал return прямо в базовой цепочке, или после goto), действует её policy (по умолчанию accept; accept значит идти дальше, drop окончателен). jump NAME входит в обычную цепочку той же таблицы и, если там не было вердикта accept/drop/reject, возвращается в следующее правило; return в обычной цепочке возвращает назад; goto не возвращает. Если все цепочки пройдены, ответ ''accept''. Именованные множества (блоки set с elements = { ... }) доступны в правилах как @имя; сами блоки set, map и другие не являются правилами. Правило - строка листинга. Условия (должны выполняться все, != отрицает следующее значение): ct state S, iif N или iifname N (поле iif пакета), ip saddr A, ip daddr A, ip protocol P или meta l4proto P (поле proto пакета), tcp dport V, udp dport V, tcp sport V, udp sport V (они же требуют proto tcp или udp). Значение - один элемент, множество в фигурных скобках или список через запятую; элемент - строка (кавычки не учитываются), порт или диапазон портов a-b, либо адрес, сеть CIDR или диапазон адресов a-b. Игнорируйте операторы counter (в том числе ''counter packets N bytes N''), log (в том числе с prefix "..." и level L), comment "...". Первое слово-вердикт завершает правило: accept, drop, reject (возможны дополнительные слова), return, jump ИМЯ, goto ИМЯ.', 'def packet_verdict(text, hook, pkt):
    pass
', 'Три слоя: разбор листинга, выбор и сортировка цепочек, обход правил с рекурсией для jump/goto. Решайте по цепочке: accept в цепочке - это ''идти дальше''.', '{"func": "packet_verdict", "tests": [{"args": ["table inet filter {\n\tset admins {\n\t\ttype ipv4_addr\n\t\tflags interval\n\t\telements = { 198.51.100.0/28, 203.0.113.7 }\n\t}\n\tchain input {\n\t\ttype filter hook input priority filter; policy drop;\n\t\tct state established,related accept\n\t\tct state invalid drop\n\t\tiif \"lo\" accept\n\t\tip saddr @admins tcp dport 22 accept\n\t\ttcp dport { 80, 443 } accept\n\t\tjump icmp_rules\n\t\tcounter packets 12 bytes 840 reject\n\t}\n\tchain icmp_rules {\n\t\tip protocol icmp accept\n\t}\n\tchain forward {\n\t\ttype filter hook forward priority filter; policy drop;\n\t}\n\tchain output {\n\t\ttype filter hook output priority filter; policy accept;\n\t}\n}\n", "input", {"iif": "eth0", "proto": "tcp", "saddr": "10.1.1.1", "daddr": "192.0.2.10", "sport": 5555, "dport": 40000, "ct": "established"}], "expected": "accept"}, {"args": ["table inet filter {\n\tset admins {\n\t\ttype ipv4_addr\n\t\tflags interval\n\t\telements = { 198.51.100.0/28, 203.0.113.7 }\n\t}\n\tchain input {\n\t\ttype filter hook input priority filter; policy drop;\n\t\tct state established,related accept\n\t\tct state invalid drop\n\t\tiif \"lo\" accept\n\t\tip saddr @admins tcp dport 22 accept\n\t\ttcp dport { 80, 443 } accept\n\t\tjump icmp_rules\n\t\tcounter packets 12 bytes 840 reject\n\t}\n\tchain icmp_rules {\n\t\tip protocol icmp accept\n\t}\n\tchain forward {\n\t\ttype filter hook forward priority filter; policy drop;\n\t}\n\tchain output {\n\t\ttype filter hook output priority filter; policy accept;\n\t}\n}\n", "input", {"iif": "eth0", "proto": "tcp", "saddr": "198.51.100.5", "daddr": "192.0.2.10", "sport": 40000, "dport": 22, "ct": "new"}], "expected": "accept"}, {"args": ["table inet filter {\n\tset admins {\n\t\ttype ipv4_addr\n\t\tflags interval\n\t\telements = { 198.51.100.0/28,