INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 13, 'la13-lockout', 2, 'func', 'Скрипт nft и момент блокировки', 'script - текст скрипта из команд nft, по одной в строке (пустые строки и строки, начинающиеся с #, не считаются командами; командам нумерация с 1). pkt - словарь уже открытой сессии администратора (как в задаче про вердикт; ct - established). Напишите функцию lockout(script, pkt): применяйте команды по порядку к пустому набору правил и после каждой проверяйте, что хук input пропускает пакет pkt (вердикт accept, расчёт как в nft: цепочки типа filter таблиц ip и inet по приоритету, accept заканчивает только свою цепочку, drop и reject окончательны, без вердикта - policy цепочки). Верните кортеж (номер первой команды, после которой пакет отбрасывается, или 0, если такой не было; True, если после последней команды пакет отбрасывается). Команды: ''nft add table F T''; ''nft add chain F T C'' (обычная цепочка) и ''nft add chain F T C { type filter hook H priority P \; [policy X \;] }'' (базовая, P - число или имя filter/raw/mangle/dstnat/srcnat/security; без policy - accept; символы \; пишутся буквально); ''nft add rule F T C ТЕКСТ'' (в конец цепочки) и ''nft insert rule F T C ТЕКСТ'' (в начало); ''nft flush chain F T C''; ''nft flush ruleset''; ''nft delete table F T''. Команда, называющая отсутствующую таблицу или цепочку, или создающая уже существующую цепочку, не меняет ничего (в nft это ошибка). Правила цепочек такие же простые, как в задаче про вердикт: условия ct state, iif/iifname, ip saddr/daddr, ip protocol, tcp/udp dport/sport и вердикты accept, drop, reject (jump и goto здесь не бывает). Значения могут быть списками через запятую, диапазонами и CIDR.', 'def lockout(script, pkt):
    pass
', 'Храните список цепочек как словари {fam, table, name, hook, prio, policy, rules}; после каждой команды пересчитывайте вердикт. Обычная цепочка без hook на вердикт не влияет.', '{"func": "lockout", "tests": [{"args": ["nft add table inet filter\nnft add chain inet filter input { type filter hook input priority 0 \\; policy drop \\; }\nnft add rule inet filter input ct state established,related accept\nnft add rule inet filter input tcp dport 22 accept\n", {"iif": "eth0", "proto": "tcp", "saddr": "198.51.100.7", "daddr": "192.0.2.10", "sport": 51514, "dport": 22, "ct": "established"}], "expected": {"__tuple__": [2, false]}}, {"args": ["# the safe order: rules first, the drop policy last (here: a drop rule at the end of an accept-policy chain)\nnft add table inet filter\nnft add chain inet filter input { type filter hook input priority 0 \\; policy accept \\; }\nnft add rule inet filter input ct state established,related accept\nnft add rule inet filter input iif lo accept\nnft add rule inet filter input tcp dport 22 accept\nnft add rule inet filter input drop\n", {"iif": "eth0", "proto": "tcp", "saddr": "198.51.100.7", "daddr": "192.0.2.10", "sport": 51514, "dport": 22, "ct": "established"}], "expected": {"__tuple__": [0, false]}}, {"args": ["nft add table inet filter\nnft add chain inet filter input { type filter hook input priority 0 \\; policy accept \\; }\nnft add rule inet filter input iif lo accept\nnft add rule inet filter input drop\nnft add rule inet filter input ct state established,related accept\nnft insert rule inet filter input tcp dport 22 accept\n", {"iif": "eth0", "proto": "tcp", "saddr": "198.51.100.7", "daddr": "192.0.2.10", "sport": 51514, "dport": 22, "ct": "established"}], "expected": {"__tuple__": [4, false]}}, {"args": ["nft add table inet filter\nnft add chain inet filter input { type filter hook input priority 0 \\; policy accept \\; }\nnft add rule inet filter input iif lo accept\nnft add rule inet filter input drop\nnft add rule inet filter input ct state established,related accept\nnft insert rule inet filter input tcp dport 22 accept\n", {"iif": "eth0", "proto": "tcp", "saddr": "198.51.100.7", "daddr": "192.0.2.10", "sport": 40000, "dport": 2222, "ct": "established"}], "expected": {"__tuple__": [4, true]}}, {"args": ["nft add table inet filter\nnft add chain inet filter input { type filter hook input priority 0 \\; policy accept \\; }\nnft add rule inet filter input ct state established,related accept\nnft flush chain inet filter input\nnft add chain inet filter strict { type filter hook input priority 5 \\; policy drop \\; }\nnft flush ruleset\nnft add table ip6 filter\nnft add chain ip6 filter input { type filter hook input priority 0 \\; policy drop \\; }\n", {"iif": "eth0", "proto": "tcp", "saddr": "198.51.100.7", "daddr": "192.0.2.10", "sport": 51514, "dport": 22, "ct": "established"}], "expected": {"__tuple__": [5, false]}}, {"args": ["nft add table inet filter\nnft add chain inet filter input { type filter hook input priority 0 \\; policy accept \\; }\nnft add rule inet filter input ct state established,related accept\nnft flush chain inet filter input\nnft add chain inet filter strict { type filter hook input priority 5 \\; policy drop \\; }\n", {"iif": "eth0", "proto": "tcp", "saddr": "198.51.100.7", "daddr": "192.0.2.10", "sport": 51514, "dport": 22, "ct": "established"}], "expected": {"__tuple__": [5, true]}}, {"args": ["# every command that names a missing table or chain fails and changes nothing\nnft add rule inet filter input drop\nnft add table inet filter\nnft add rule inet filter input drop\nnft add chain inet filter input { type filter hook input priority 0 \\; policy accept \\; }\nnft add rule inet filter input ip saddr 198.51.100.0/24 tcp dport 22 accept\nnft add chain inet filter input { type filter hook input priority 0 \\; policy drop \\; }\nnft add chain inet filter extra { type filter hook input priority 10 \\; policy drop \\; }\nnft delete table inet filter\n", {"iif": "eth0", "proto": "tcp", "saddr": "198.51.100.7", "daddr": "192.0.2.10", "sport": 51514, "dport": 22, "ct": "established"}], "expected": {"__tuple__": [7, false]}}, {"args": ["nft add table inet filter\nnft add chain inet filter input { type filter hook input priority filter \\; policy drop \\; }\nnft add rule inet filter input ip saddr 203.0.113.0/24 tcp dport 22 accept\nnft add rule inet filter input ct state established accept\n", {"iif": "eth0", "proto": "tcp", "saddr": "198.51.100.7", "daddr": "192.0.2.10", "sport": 51514, "dport": 22, "ct": "established"}], "expected": {"__tuple__": [2, false]}}, {"args": ["nft add table inet filter\nnft add chain inet filter input { type filter hook input priority filter \\; policy drop \\; }\nnft add rule inet filter input ip saddr 203.0.113.0/24 tcp dport 22 accept\nnft add rule inet filter input ct state established accept\n", {"iif": "eth0", "proto": "tcp", "saddr": "203.0.113.9", "daddr": "192.0.2.10", "sport": 40000, "dport": 22, "ct": "established"}], "expected": {"__tuple__": [2, false]}}, {"args": ["nft add table inet filter\nnft add chain inet filter input { type filter hook input priority filter \\; policy drop \\; }\nnft add rule inet filter input ip saddr 203.0.113.0/24 tcp dport 22 accept\n", {"iif": "eth0", "proto": "tcp", "saddr": "203.0.113.9", "daddr": "192.0.2.10", "sport": 40000, "dport": 2222, "ct": "established"}], "expected": {"__tuple__": [2, true]}}, {"args": ["", {"iif": "eth0", "proto": "tcp", "saddr": "198.51.100.7", "daddr": "192.0.2.10", "sport": 51514, "dport": 22, "ct": "established"}], "expected": {"__tuple__": [0, false]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 13, 'la13-nat', 3, 'func', 'Подмена адреса назначения', 'text - вывод nft list ruleset, pkt - словарь пакета с ключами iif, proto (tcp или udp), daddr и dport, local_ip - основной адрес входного интерфейса. Напишите функцию nat_translate(text, pkt, local_ip): верните строку ''адрес:порт'' - куда будет доставлен первый пакет соединения после подмены в хуке prerouting. Учитываются цепочки типа nat на хуке prerouting таблиц ip и inet в порядке возрастания приоритета (имена как в nft: dstnat -100, filter 0..., возможно со смещением ''dstnat + 5'', при равенстве порядок появления); цепочки других типов (filter) игнорируйте. Правила идут по порядку; перед словом dnat или redirect стоят условия (iifname N, ip daddr A, ip protocol P, tcp dport V, udp dport V, значение может быть множеством в фигурных скобках, диапазоном a-b или CIDR; != отрицает значение; операторы counter, в том числе ''counter packets N bytes N'', игнорируются). Первое подошедшее правило с dnat или redirect выполняется, и обработка заканчивается. ''dnat [ip] to A'' меняет адрес, порт остаётся; ''dnat [ip] to A:P'' меняет и порт; ''dnat [ip] to tcp dport map { P1 : A1, P2 : A2 }'' (или udp) берёт адрес по порту назначения, порт не меняется, и правило не подходит, если протокол пакета другой или порта нет в словаре (поиск неудачен - переходим к следующему правилу); ''redirect to P'' и ''redirect to :P'' заменяют адрес на local_ip и порт на P. Если ничего не подошло, верните исходный ''daddr:dport''.', 'def nat_translate(text, pkt, local_ip):
    pass
', 'Условия - всё, что стоит до слова dnat/redirect: разберите их тем же способом, что условия обычных правил. Не забудьте, что словарь по порту не меняет порт.', '{"func": "nat_translate", "tests": [{"args": ["table ip nat {\n\tchain prerouting {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\tiifname \"eth0\" tcp dport 8080 dnat to 10.0.0.5:80\n\t\tiifname \"eth0\" tcp dport { 2222, 2223 } dnat to 10.0.0.6:22\n\t\tiifname \"eth0\" tcp dport 53 redirect to :5353\n\t\tip daddr 192.0.2.10 tcp dport 443 dnat to 10.0.0.7\n\t}\n\tchain postrouting {\n\t\ttype nat hook postrouting priority srcnat; policy accept;\n\t\toifname \"eth0\" masquerade\n\t}\n}\n", {"iif": "eth0", "proto": "tcp", "saddr": "203.0.113.50", "daddr": "192.0.2.10", "sport": 40000, "dport": 8080, "ct": "new"}, "192.0.2.1"], "expected": "10.0.0.5:80"}, {"args": ["table ip nat {\n\tchain prerouting {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\tiifname \"eth0\" tcp dport 8080 dnat to 10.0.0.5:80\n\t\tiifname \"eth0\" tcp dport { 2222, 2223 } dnat to 10.0.0.6:22\n\t\tiifname \"eth0\" tcp dport 53 redirect to :5353\n\t\tip daddr 192.0.2.10 tcp dport 443 dnat to 10.0.0.7\n\t}\n\tchain postrouting {\n\t\ttype nat hook postrouting priority srcnat; policy accept;\n\t\toifname \"eth0\" masquerade\n\t}\n}\n", {"iif": "eth0", "proto": "tcp", "saddr": "203.0.113.50", "daddr": "192.0.2.10", "sport": 40000, "dport": 2223, "ct": "new"}, "192.0.2.1"], "expected": "10.0.0.6:22"}, {"args": ["table ip nat {\n\tchain prerouting {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\tiifname \"eth0\" tcp dport 8080 dnat to 10.0.0.5:80\n\t\tiifname \"eth0\" tcp dport { 2222, 2223 } dnat to 10.0.0.6:22\n\t\tiifname \"eth0\" tcp dport 53 redirect to :5353\n\t\tip daddr 192.0.2.10 tcp dport 443 dnat to 10.0.0.7\n\t}\n\tchain postrouting {\n\t\ttype nat hook postrouting priority srcnat; policy accept;\n\t\toifname \"eth0\" masquerade\n\t}\n}\n", {"iif": "eth0", "proto": "udp", "saddr": "203.0.113.50", "daddr": "192.0.2.10", "sport": 40000, "dport": 53, "ct": "new"}, "192.0.2.1"], "expected": "192.0.2.10:53"}, {"args": ["table ip nat {\n\tchain prerouting {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\tiifname \"eth0\" tcp dport 8080 dnat to 10.0.0.5:80\n\t\tiifname \"eth0\" tcp dport { 2222, 2223 } dnat to 10.0.0.6:22\n\t\tiifname \"eth0\" tcp dport 53 redirect to :5353\n\t\tip daddr 192.0.2.10 tcp dport 443 dnat to 10.0.0.7\n\t}\n\tchain postrouting {\n\t\ttype nat hook postrouting priority srcnat; policy accept;\n\t\toifname \"eth0\" masquerade\n\t}\n}\n", {"iif": "eth0", "proto": "tcp", "saddr": "203.0.113.50", "daddr": "192.0.2.10", "sport": 40000, "dport": 53, "ct": "new"}, "192.0.2.1"], "expected": "192.0.2.1:5353"}, {"args": ["table ip nat {\n\tchain prerouting {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\tiifname \"eth0\" tcp dport 8080 dnat to 10.0.0.5:80\n\t\tiifname \"eth0\" tcp dport { 2222, 2223 } dnat to 10.0.0.6:22\n\t\tiifname \"eth0\" tcp dport 53 redirect to :5353\n\t\tip daddr 192.0.2.10 tcp dport 443 dnat to 10.0.0.7\n\t}\n\tchain postrouting {\n\t\ttype nat hook postrouting priority srcnat; policy accept;\n\t\toifname \"eth0\" masquerade\n\t}\n}\n", {"iif": "eth1", "proto": "tcp", "saddr": "203.0.113.50", "daddr": "192.0.2.10", "sport": 40000, "dport": 443, "ct": "new"}, "192.0.2.1"], "expected": "10.0.0.7:443"}, {"args": ["table ip nat {\n\tchain prerouting {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\tiifname \"eth0\" tcp dport 8080 dnat to 10.0.0.5:80\n\t\tiifname \"eth0\" tcp dport { 2222, 2223 } dnat to 10.0.0.6:22\n\t\tiifname \"eth0\" tcp dport 53 redirect to :5353\n\t\tip daddr 192.0.2.10 tcp dport 443 dnat to 10.0.0.7\n\t}\n\tchain postrouting {\n\t\ttype nat hook postrouting priority srcnat; policy accept;\n\t\toifname \"eth0\" masquerade\n\t}\n}\n", {"iif": "eth1", "proto": "tcp", "saddr": "203.0.113.50", "daddr": "192.0.2.99", "sport": 40000, "dport": 443, "ct": "new"}, "192.0.2.1"], "expected": "192.0.2.99:443"}, {"args": ["table ip nat {\n\tchain prerouting {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\tiifname \"eth0\" tcp dport 8080 dnat to 10.0.0.5:80\n\t\tiifname \"eth0\" tcp dport { 2222, 2223 } dnat to 10.0.0.6:22\n\t\tiifname \"eth0\" tcp dport 53 redirect to :5353\n\t\tip daddr 192.0.2.10 tcp dport 443 dnat to 10.0.0.7\n\t}\n\tchain postrouting {\n\t\ttype nat hook postrouting priority srcnat; policy accept;\n\t\toifname \"eth0\" masquerade\n\t}\n}\n", {"iif": "eth1", "proto": "tcp", "saddr": "203.0.113.50", "daddr": "192.0.2.10", "sport": 40000, "dport": 8080, "ct": "new"}, "192.0.2.1"], "expected": "192.0.2.10:8080"}, {"args": ["table ip nat {\n\tchain prerouting {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\tdnat to tcp dport map { 80 : 10.0.0.5, 8443 : 10.0.0.6 }\n\t\tudp dport 5060 dnat to 10.0.0.9:5080\n\t}\n}\n", {"iif": "eth0", "proto": "tcp", "saddr": "203.0.113.50", "daddr": "192.0.2.10", "sport": 40000, "dport": 80, "ct": "new"}, "192.0.2.1"], "expected": "10.0.0.5:80"}, {"args": ["table ip nat {\n\tchain prerouting {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\tdnat to tcp dport map { 80 : 10.0.0.5, 8443 : 10.0.0.6 }\n\t\tudp dport 5060 dnat to 10.0.0.9:5080\n\t}\n}\n", {"iif": "eth0", "proto": "tcp", "saddr": "203.0.113.50", "daddr": "192.0.2.10", "sport": 40000, "dport": 8443, "ct": "new"}, "192.0.2.1"], "expected": "10.0.0.6:8443"}, {"args": ["table ip nat {\n\tchain prerouting {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\tdnat to tcp dport map { 80 : 10.0.0.5, 8443 : 10.0.0.6 }\n\t\tudp dport 5060 dnat to 10.0.0.9:5080\n\t}\n}\n", {"iif": "eth0", "proto": "tcp", "saddr": "203.0.113.50", "daddr": "192.0.2.10", "sport": 40000, "dport": 22, "ct": "new"}, "192.0.2.1"], "expected": "192.0.2.10:22"}, {"args": ["table ip nat {\n\tchain prerouting {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\tdnat to tcp dport map { 80 : 10.0.0.5, 8443 : 10.0.0.6 }\n\t\tudp dport 5060 dnat to 10.0.0.9:5080\n\t}\n}\n", {"iif": "eth0", "proto": "udp", "saddr": "203.0.113.50", "daddr": "192.0.2.10", "sport": 40000, "dport": 5060, "ct": "new"}, "192.0.2.1"], "expected": "10.0.0.9:5080"}, {"args": ["table ip nat {\n\tchain prerouting {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\tdnat to tcp dport map { 80 : 10.0.0.5, 8443 : 10.0.0.6 }\n\t\tudp dport 5060 dnat to 10.0.0.9:5080\n\t}\n}\n", {"iif": "eth0", "proto": "udp", "saddr": "203.0.113.50", "daddr": "192.0.2.10", "sport": 40000, "dport": 80, "ct": "new"}, "192.0.2.1"], "expected": "192.0.2.10:80"}, {"args": ["table inet late {\n\tchain pre {\n\t\ttype nat hook prerouting priority dstnat + 5; policy accept;\n\t\ttcp dport 80 dnat ip to 10.5.5.5:8080\n\t}\n}\ntable inet early {\n\tchain pre {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\tiifname != \"lo\" tcp dport 80 ip daddr 192.0.2.10 dnat ip to 10.1.1.1\n\t\ttcp dport 8080 counter packets 3 bytes 180 redirect to 3128\n\t}\n}\ntable inet capture {\n\tchain pre {\n\t\ttype filter hook prerouting priority -100; policy accept;\n\t\ttcp dport 80 drop\n\t}\n}\n", {"iif": "eth0", "proto": "tcp", "saddr": "203.0.113.50", "daddr": "192.0.2.10", "sport": 40000, "dport": 80, "ct": "new"}, "192.0.2.1"], "expected": "10.1.1.1:80"}, {"args": ["table inet late {\n\tchain pre {\n\t\ttype nat hook prerouting priority dstnat + 5; policy accept;\n\t\ttcp dport 80 dnat ip to 10.5.5.5:8080\n\t}\n}\ntable inet early {\n\tchain pre {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\tiifname != \"lo\" tcp dport 80 ip daddr 192.0.2.10 dnat ip to 10.1.1.1\n\t\ttcp dport 8080 counter packets 3 bytes 180 redirect to 3128\n\t}\n}\ntable inet capture {\n\tchain pre {\n\t\ttype filter hook prerouting priority -100; policy accept;\n\t\ttcp dport 80 drop\n\t}\n}\n", {"iif": "eth0", "proto": "tcp", "saddr": "203.0.113.50", "daddr": "192.0.2.99", "sport": 40000, "dport": 80, "ct": "new"}, "192.0.2.1"], "expected": "10.5.5.5:8080"}, {"args": ["table inet late {\n\tchain pre {\n\t\ttype nat hook prerouting priority dstnat + 5; policy accept;\n\t\ttcp dport 80 dnat ip to 10.5.5.5:8080\n\t}\n}\ntable inet early {\n\tchain pre {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\tiifname != \"lo\" tcp dport 80 ip daddr 192.0.2.10 dnat ip to 10.1.1.1\n\t\ttcp dport 8080 counter packets 3 bytes 180 redirect to 3128\n\t}\n}\ntable inet capture {\n\tchain pre {\n\t\ttype filter hook prerouting priority -100; policy accept;\n\t\ttcp dport 80 drop\n\t}\n}\n", {"iif": "lo", "proto": "tcp", "saddr": "203.0.113.50", "daddr": "192.0.2.10", "sport": 40000, "dport": 80, "ct": "new"}, "192.0.2.1"], "expected": "10.5.5.5:8080"}, {"args": ["table inet late {\n\tchain pre {\n\t\ttype nat hook prerouting priority dstnat + 5; policy accept;\n\t\ttcp dport 80 dnat ip to 10.5.5.5:8080\n\t}\n}\ntable inet early {\n\tchain pre {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\tiifname != \"lo\" tcp dport 80 ip daddr 192.0.2.10 dnat ip to 10.1.1.1\n\t\ttcp dport 8080 counter packets 3 bytes 180 redirect to 3128\n\t}\n}\ntable inet capture {\n\tchain pre {\n\t\ttype filter hook prerouting priority -100; policy accept;\n\t\ttcp dport 80 drop\n\t}\n}\n", {"iif": "eth0", "proto": "tcp", "saddr": "203.0.113.50", "daddr": "192.0.2.99", "sport": 40000, "dport": 8080, "ct": "new"}, "198.51.100.1"], "expected": "198.51.100.1:3128"}, {"args": ["table inet late {\n\tchain pre {\n\t\ttype nat hook prerouting priority dstnat + 5; policy accept;\n\t\ttcp dport 80 dnat ip to 10.5.5.5:8080\n\t}\n}\ntable inet early {\n\tchain pre {\n\t\ttype nat hook prerouting priority dstnat; policy accept;\n\t\tiifname != \"lo\" tcp dport 80 ip daddr 192.0.2.10 dnat ip to 10.1.1.1\n\t\ttcp dport 8080 counter packets 3 bytes 180 redirect to 3128\n\t}\n}\ntable inet capture {\n\tchain pre {\n\t\ttype filter hook prerouting priority -100; policy accept;\n\t\ttcp dport 80 drop\n\t}\n}\n", {"iif": "eth0", "proto": "tcp", "saddr": "203.0.113.50", "daddr": "192.0.2.99", "sport": 40000, "dport": 25, "ct": "new"}, "198.51.100.1"], "expected": "192.0.2.99:25"}, {"args": ["", {"iif": "eth0", "proto": "tcp", "saddr": "203.0.113.50", "daddr": "192.0.2.10", "sport": 40000, "dport": 80, "ct": "new"}, "192.0.2.1"], "expected": "192.0.2.10:80"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 13, 'la13-set-members', 4, 'func', 'Вхождение в множество из листинга', 'text - вывод nft list set (или list ruleset с одним множеством). Напишите функцию set_contains(text, values): верните список bool - входит ли каждое значение из values в множество. Тип задан строкой ''type ipv4_addr'', ''type ipv6_addr'', ''type inet_service'' либо ''typeof ip saddr'' / ''typeof ip daddr'' (IPv4), ''typeof ip6 saddr'' / ''typeof ip6 daddr'' (IPv6), ''typeof tcp dport'' / ''typeof udp dport'' / ''typeof tcp sport'' / ''typeof udp sport'' (порты). Для адресных множеств values - строки с адресами, для портов - целые числа. Элементы лежат в строке(ах) ''elements = { ... }'', разделены запятыми и могут быть перенесены на следующие строки. Элемент - адрес, сеть CIDR или диапазон a-b (адресов или портов); у портов вместо числа может стоять имя службы: ssh 22, domain 53, http 80, https 443, smtp 25, imap 143, mysql 3306. После элемента могут идти слова timeout T, expires T и comment "..." - они не меняют сам элемент. Если строки elements нет, множество пусто.', 'def set_contains(text, values):
    pass
', 're.search(r''elements = \{(.*?)\}'', text, re.S); каждый элемент - первое слово после разбиения по запятым. Переведите всё в целые числа и сравнивайте с диапазонами.', '{"func": "set_contains", "tests": [{"args": ["table inet filter {\n\tset admins {\n\t\ttype ipv4_addr\n\t\tflags interval\n\t\telements = { 10.0.0.0/24, 192.168.1.5,\n\t\t\t\t\t 172.16.0.1-172.16.0.9 }\n\t}\n}\n", ["10.0.0.77", "192.168.1.5", "192.168.1.6", "172.16.0.9", "172.16.0.10", "10.0.1.0"]], "expected": [true, true, false, true, false, false]}, {"args": ["table inet filter {\n\tset banned {\n\t\ttype ipv4_addr\n\t\tsize 65536\n\t\tflags dynamic,timeout\n\t\ttimeout 1h\n\t\telements = { 203.0.113.9 timeout 1h expires 59m31s, 198.51.100.77 timeout 1h expires 12m3s }\n\t}\n}\n", ["203.0.113.9", "198.51.100.77", "203.0.113.10"]], "expected": [true, true, false]}, {"args": ["table inet filter {\n\tset mgmt_ports {\n\t\ttype inet_service\n\t\tflags interval\n\t\telements = { ssh, domain, 8000-8010, https, 9090 }\n\t}\n}\n", [22, 53, 8005, 443, 8011, 9090, 80]], "expected": [true, true, true, true, false, true, false]}, {"args": ["table inet filter {\n\tset empty {\n\t\ttype ipv4_addr\n\t}\n}\n", ["1.1.1.1"]], "expected": [false]}, {"args": ["table inet filter {\n\tset v6net {\n\t\ttypeof ip6 saddr\n\t\tflags interval\n\t\telements = { 2001:db8::/32, fd00::1-fd00::ff }\n\t}\n}\n", ["2001:db8:1::1", "fd00::80", "fd00::100", "2001:db9::1"]], "expected": [true, true, false, false]}, {"args": ["table inet filter {\n\tset web {\n\t\ttypeof tcp dport\n\t\telements = { http, https, 8080 comment \"alt\", mysql }\n\t}\n}\n", [80, 443, 8080, 3306, 22]], "expected": [true, true, true, true, false]}, {"args": ["table inet filter {\n\tset admins {\n\t\ttype ipv4_addr\n\t\tflags interval\n\t\telements = { 10.0.0.0/24, 192.168.1.5,\n\t\t\t\t\t 172.16.0.1-172.16.0.9 }\n\t}\n}\n", []], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 13, 'la13-ct-replay', 5, 'func', 'Слежение за соединениями и input', 'Напишите функцию ct_replay(policy, rules, events): policy - ''accept'' или ''drop'' (политика цепочки input), rules - список строк правил этой цепочки, events - список кортежей (direction, proto, src, sport, dst, dport) в порядке прибытия; direction ''out'' - пакет, созданный самим хостом (цепочка output пропускает всё, но соединение отслеживается), ''in'' - пакет, пришедший на интерфейс eth0 и идущий в цепочку input. Верните список вердиктов (''accept'', ''drop'' или ''reject'') для каждого события; для ''out'' всегда ''accept''. Состояние ct пакета вычисляется так: если в таблице соединений нет записи ни с кортежем (proto, src, sport, dst, dport), ни с обратным (proto, dst, dport, src, sport), состояние new; пакет по прямому кортежу записи - new, пока ответ не был принят, и established после; пакет по обратному кортежу - established. Запись создаётся только если первый пакет принят (accept), отмечается ''ответ был'' только когда принят ответный пакет; отброшенные пакеты записи не создают и не меняют. В rules используются условия ct state, iif/iifname (пакет приходит на eth0), ip saddr, ip daddr, ip protocol, tcp/udp dport/sport и вердикты accept, drop, reject; первый вердикт решает, иначе действует policy. Значения - как в nft: списки через запятую, множества, диапазоны a-b, сети CIDR.', 'def ct_replay(policy, rules, events):
    pass
', 'Храните словарь прямых кортежей -> {''replied'': bool}. Сначала вычислите состояние, потом вердикт, и только после accept меняйте таблицу.', '{"func": "ct_replay", "tests": [{"args": ["drop", ["ct state established,related accept", "tcp dport 22 accept"], [{"__tuple__": ["in", "tcp", "203.0.113.5", 40000, "192.0.2.10", 22]}, {"__tuple__": ["out", "tcp", "192.0.2.10", 22, "203.0.113.5", 40000]}, {"__tuple__": ["in", "tcp", "203.0.113.5", 40000, "192.0.2.10", 22]}, {"__tuple__": ["in", "tcp", "203.0.113.5", 40001, "192.0.2.10", 23]}]], "expected": ["accept", "accept", "accept", "drop"]}, {"args": ["drop", ["ct state established,related accept"], [{"__tuple__": ["out", "udp", "192.0.2.10", 55000, "198.51.100.53", 53]}, {"__tuple__": ["in", "udp", "198.51.100.53", 53, "192.0.2.10", 55000]}, {"__tuple__": ["in", "udp", "198.51.100.54", 53, "192.0.2.10", 55000]}, {"__tuple__": ["in", "udp", "198.51.100.53", 53, "192.0.2.10", 55001]}]], "expected": ["accept", "accept", "drop", "drop"]}, {"args": ["drop", ["ct state established accept", "tcp dport 80 accept"], [{"__tuple__": ["in", "tcp", "203.0.113.5", 40000, "192.0.2.10", 80]}, {"__tuple__": ["in", "tcp", "203.0.113.5", 40000, "192.0.2.10", 80]}, {"__tuple__": ["out", "tcp", "192.0.2.10", 80, "203.0.113.5", 40000]}, {"__tuple__": ["in", "tcp", "203.0.113.5", 40000, "192.0.2.10", 80]}]], "expected": ["accept", "accept", "accept", "accept"]}, {"args": ["drop", ["ct state established accept", "ip saddr 198.51.100.0/24 drop", "tcp dport 22 accept"], [{"__tuple__": ["in", "tcp", "198.51.100.8", 50000, "192.0.2.10", 22]}, {"__tuple__": ["in", "tcp", "203.0.113.5", 50000, "192.0.2.10", 22]}, {"__tuple__": ["out", "tcp", "192.0.2.10", 22, "203.0.113.5", 50000]}, {"__tuple__": ["in", "tcp", "203.0.113.5", 50000, "192.0.2.10", 22]}, {"__tuple__": ["in", "tcp", "198.51.100.8", 50000, "192.0.2.10", 22]}]], "expected": ["drop", "accept", "accept", "accept", "drop"]}, {"args": ["drop", ["tcp dport 80 accept"], [{"__tuple__": ["in", "tcp", "203.0.113.5", 40000, "192.0.2.10", 80]}, {"__tuple__": ["in", "tcp", "203.0.113.5", 40000, "192.0.2.10", 80]}, {"__tuple__": ["out", "tcp", "192.0.2.10", 80, "203.0.113.5", 40000]}, {"__tuple__": ["in", "tcp", "203.0.113.5", 40000, "192.0.2.10", 80]}]], "expected": ["accept", "accept", "accept", "accept"]}, {"args": ["drop", ["ct state established accept"], [{"__tuple__": ["in", "tcp", "203.0.113.5", 40000, "192.0.2.10", 80]}, {"__tuple__": ["in", "tcp", "203.0.113.5", 40000, "192.0.2.10", 80]}, {"__tuple__": ["out", "tcp", "192.0.2.10", 80, "203.0.113.5", 40000]}, {"__tuple__": ["in", "tcp", "203.0.113.5", 40000, "192.0.2.10", 80]}]], "expected": ["drop", "drop", "accept", "accept"]}, {"args": ["drop", ["ct state established accept"], [{"__tuple__": ["in", "tcp", "203.0.113.5", 40000, "192.0.2.10", 22]}, {"__tuple__": ["out", "tcp", "192.0.2.10", 22, "203.0.113.5", 40000]}, {"__tuple__": ["in", "tcp", "203.0.113.5", 40000, "192.0.2.10", 22]}, {"__tuple__": ["in", "tcp", "203.0.113.5", 40001, "192.0.2.10", 23]}]], "expected": ["drop", "accept", "accept", "drop"]}, {"args": ["accept", [], [{"__tuple__": ["in", "tcp", "203.0.113.5", 40000, "192.0.2.10", 22]}, {"__tuple__": ["out", "tcp", "192.0.2.10", 22, "203.0.113.5", 40000]}, {"__tuple__": ["in", "tcp", "203.0.113.5", 40000, "192.0.2.10", 22]}, {"__tuple__": ["in", "tcp", "203.0.113.5", 40001, "192.0.2.10", 23]}]], "expected": ["accept", "accept", "accept", "accept"]}, {"args": ["accept", ["ct state new tcp dport 23 reject"], [{"__tuple__": ["in", "tcp", "203.0.113.5", 40000, "192.0.2.10", 22]}, {"__tuple__": ["out", "tcp", "192.0.2.10", 22, "203.0.113.5", 40000]}, {"__tuple__": ["in", "tcp", "203.0.113.5", 40000, "192.0.2.10", 22]}, {"__tuple__": ["in", "tcp", "203.0.113.5", 40001, "192.0.2.10", 23]}]], "expected": ["accept", "accept", "accept", "reject"]}, {"args": ["drop", [], []], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 13, 'la13-list-all', 6, 'func', 'firewall-cmd --list-all в разрешения', 'text - вывод firewall-cmd --list-all (формат firewalld 2.x: первая строка - имя зоны и необязательные пометки в скобках через запятую, например ''public (default, active)''; дальше строки ''  ключ: значения'' с двумя пробелами; для forward-ports и rich rules значения лежат на следующих строках, начинающихся с табуляции; пустое значение может быть без пробела после двоеточия; лишние ключи игнорируйте). services - словарь служб {имя: список строк ''порт/протокол''}. Напишите функцию firewall_summary(text, services): верните словарь с ключами zone (имя), default и active (bool по пометкам), target (''reject'' для default и %%REJECT%%, ''accept'' для ACCEPT, ''drop'' для DROP), open (отсортированный список уникальных ''порт/протокол'' из служб zone (неизвестные службы пропускайте) и из ports; диапазоны вида 9000-9010/tcp сохраняются; сортировка по протоколу как строке, затем по первому порту, затем по последнему), protocols (отсортированный список из protocols), masquerade (bool), rich (список строк из rich rules в порядке вывода) и forwards (список из forward-ports). Богатое правило даёт строки ''действие цель from источник'', где действие - последнее слово правила (accept, reject или drop; правила с другим последним словом пропускайте), источник - source address="..." или ''any'', цель - ''порт/протокол'' для port port="P" protocol="T", по одной строке на каждый порт службы для service name="S" (в порядке списка службы) или ''all'', если в правиле нет ни порта, ни службы; правила с masquerade, forward-port, icmp-block, icmp-type, protocol и source-port пропускайте. Строка forward-ports ''port=P:proto=T:toport=Q:toaddr=A'' даёт ''P/T -> A:Q'' (пустой toport означает тот же порт P, пустой toaddr остаётся пустым).', 'def firewall_summary(text, services):
    pass
', 'Строки без пробела в начале - заголовок, строки с табуляцией - продолжение предыдущего ключа. Для сортировки портов используйте ключ (протокол, начало, конец).', '{"func": "firewall_summary", "tests": [{"args": ["public (default, active)\n  target: default\n  ingress-priority: 0\n  egress-priority: 0\n  icmp-block-inversion: no\n  interfaces: eth0\n  sources: \n  services: cockpit dhcpv6-client ssh\n  ports: \n  protocols: \n  forward: yes\n  masquerade: no\n  forward-ports: \n  source-ports: \n  icmp-blocks: \n  rich rules: \n", {"ssh": ["22/tcp"], "http": ["80/tcp"], "https": ["443/tcp"], "dns": ["53/tcp", "53/udp"], "dhcpv6-client": ["546/udp"], "cockpit": ["9090/tcp"], "samba": ["139/tcp", "445/tcp"], "mdns": ["5353/udp"]}], "expected": {"zone": "public", "default": true, "active": true, "target": "reject", "open": ["22/tcp", "9090/tcp", "546/udp"], "protocols": [], "masquerade": false, "rich": [], "forwards": []}}, {"args": ["public (default, active)\n  target: default\n  ingress-priority: 0\n  egress-priority: 0\n  icmp-block-inversion: no\n  interfaces: eth0 eth1\n  sources: \n  services: dns http https ssh\n  ports: 8080/tcp 9000-9010/tcp 5000/udp\n  protocols: gre\n  forward: yes\n  masquerade: no\n  forward-ports: \n  source-ports: \n  icmp-blocks: \n  rich rules: \n\trule family=\"ipv4\" source address=\"10.0.0.0/8\" service name=\"samba\" accept\n\trule family=\"ipv4\" source address=\"203.0.113.0/24\" port port=\"22\" protocol=\"tcp\" reject\n\trule service name=\"mdns\" drop\n\trule family=\"ipv4\" source address=\"198.51.100.9\" drop\n", {"ssh": ["22/tcp"], "http": ["80/tcp"], "https": ["443/tcp"], "dns": ["53/tcp", "53/udp"], "dhcpv6-client": ["546/udp"], "cockpit": ["9090/tcp"], "samba": ["139/tcp", "445/tcp"], "mdns": ["5353/udp"]}], "expected": {"zone": "public", "default": true, "active": true, "target": "reject", "open": ["22/tcp", "53/tcp", "80/tcp", "443/tcp", "8080/tcp", "9000-9010/tcp", "53/udp", "5000/udp"], "protocols": ["gre"], "masquerade": false, "rich": ["accept 139/tcp from 10.0.0.0/8", "accept 445/tcp from 10.0.0.0/8", "reject 22/tcp from 203.0.113.0/24", "drop 5353/udp from any", "drop all from 198.51.100.9"], "forwards": []}}, {"args": ["trusted (active)\n  target: ACCEPT\n  ingress-priority: 0\n  egress-priority: 0\n  icmp-block-inversion: no\n  interfaces: \n  sources: 10.8.0.0/16\n  services: \n  ports: \n  protocols: \n  forward: yes\n  masquerade: no\n  forward-ports: \n  source-ports: \n  icmp-blocks: \n  rich rules: \n", {"ssh": ["22/tcp"], "http": ["80/tcp"], "https": ["443/tcp"], "dns": ["53/tcp", "53/udp"], "dhcpv6-client": ["546/udp"], "cockpit": ["9090/tcp"], "samba": ["139/tcp", "445/tcp"], "mdns": ["5353/udp"]}], "expected": {"zone": "trusted", "default": false, "active": true, "target": "accept", "open": [], "protocols": [], "masquerade": false, "rich": [], "forwards": []}}, {"args": ["drop\n  target: DROP\n  ingress-priority: 0\n  egress-priority: 0\n  icmp-block-inversion: no\n  interfaces: \n  sources: \n  services: \n  ports: \n  protocols: \n  forward: yes\n  masquerade: no\n  forward-ports: \n  source-ports: \n  icmp-blocks: \n  rich rules: \n", {"ssh": ["22/tcp"], "http": ["80/tcp"], "https": ["443/tcp"], "dns": ["53/tcp", "53/udp"], "dhcpv6-client": ["546/udp"], "cockpit": ["9090/tcp"], "samba": ["139/tcp", "445/tcp"], "mdns": ["5353/udp"]}], "expected": {"zone": "drop", "default": false, "active": false, "target": "drop", "open": [], "protocols": [], "masquerade": false, "rich": [], "forwards": []}}, {"args": ["external (active)\n  target: default\n  ingress-priority: 0\n  egress-priority: 0\n  icmp-block-inversion: no\n  interfaces: eth1\n  sources: \n  services: ssh\n  ports: \n  protocols: \n  forward: no\n  masquerade: yes\n  forward-ports: \n\tport=8080:proto=tcp:toport=80:toaddr=10.0.0.5\n\tport=2222:proto=tcp:toport=:toaddr=10.0.0.6\n\tport=53:proto=udp:toport=5353:toaddr=\n  source-ports: \n  icmp-blocks: \n  rich rules: \n\trule family=\"ipv4\" priority=\"-10\" source address=\"192.0.2.0/24\" accept\n\trule family=\"ipv4\" masquerade\n\trule family=\"ipv4\" port port=\"8443\" protocol=\"tcp\" log prefix=\"x\" level=\"info\" accept\n", {"ssh": ["22/tcp"], "http": ["80/tcp"], "https": ["443/tcp"], "dns": ["53/tcp", "53/udp"], "dhcpv6-client": ["546/udp"], "cockpit": ["9090/tcp"], "samba": ["139/tcp", "445/tcp"], "mdns": ["5353/udp"]}], "expected": {"zone": "external", "default": false, "active": true, "target": "reject", "open": ["22/tcp"], "protocols": [], "masquerade": true, "rich": ["accept all from 192.0.2.0/24", "accept 8443/tcp from any"], "forwards": ["8080/tcp -> 10.0.0.5:80", "2222/tcp -> 10.0.0.6:2222", "53/udp -> :5353"]}}, {"args": ["block (active)\n  target: %%REJECT%%\n  ingress-priority: 0\n  egress-priority: 0\n  icmp-block-inversion: no\n  interfaces: eth2\n  sources: \n  services: unknown-service ssh\n  ports: 1000-2000/udp 22/tcp 22/udp\n  protocols: \n  forward: yes\n  masquerade: no\n  forward-ports: \n  source-ports: \n  icmp-blocks: \n  rich rules: \n", {"ssh": ["22/tcp"], "http": ["80/tcp"], "https": ["443/tcp"], "dns": ["53/tcp", "53/udp"], "dhcpv6-client": ["546/udp"], "cockpit": ["9090/tcp"], "samba": ["139/tcp", "445/tcp"], "mdns": ["5353/udp"]}], "expected": {"zone": "block", "default": false, "active": true, "target": "reject", "open": ["22/tcp", "22/udp", "1000-2000/udp"], "protocols": [], "masquerade": false, "rich": [], "forwards": []}}, {"args": ["public (default, active)\n  target: default\n  ingress-priority: 0\n  egress-priority: 0\n  icmp-block-inversion: no\n  interfaces: eth0\n  sources: \n  services: cockpit dhcpv6-client ssh\n  ports: \n  protocols: \n  forward: yes\n  masquerade: no\n  forward-ports: \n  source-ports: \n  icmp-blocks: \n  rich rules: \n", {}], "expected": {"zone": "public", "default": true, "active": true, "target": "reject", "open": [], "protocols": [], "masquerade": false, "rich": [], "forwards": []}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 13, 'la13-zone-select', 7, 'func', 'Выбор зоны firewalld', 'active - вывод firewall-cmd --get-active-zones: строка с именем зоны (после имени может стоять '' (default)''), под ней строки ''  interfaces: ...'' и ''  sources: ...'' с пробелами между значениями; в sources бывают сети CIDR (IPv4 и IPv6), MAC-адреса и ipset:имя. priorities - словарь {зона: ingress-priority}, для зон вне словаря приоритет 0. Напишите функцию zone_select(active, priorities, default_zone, iface, saddr): верните имя зоны, которая обработает пакет, пришедший на интерфейс iface с адреса saddr. Зона-кандидат - зона, у которой в sources есть сеть, содержащая saddr (MAC и ipset игнорируйте), либо в interfaces есть iface; если подходят оба признака, зона считается кандидатом по источнику. Побеждает кандидат с меньшим приоритетом; при равенстве приоритетов кандидаты по источнику идут раньше кандидатов по интерфейсу, а внутри группы - по имени зоны в алфавитном порядке. Если кандидатов нет, верните default_zone.', 'def zone_select(active, priorities, default_zone, iface, saddr):
    pass
', 'Ключ сортировки кандидата: (приоритет, 0 если по источнику иначе 1, имя). ipaddress.ip_network(s, strict=False) бросает ValueError на MAC и ipset.', '{"func": "zone_select", "tests": [{"args": ["public (default)\n  interfaces: eth0\ninternal\n  interfaces: eth1\n  sources: 192.168.50.0/24\ntrusted\n  sources: 10.8.0.0/16 fd00::/8\n", {}, "public", "eth0", "8.8.8.8"], "expected": "public"}, {"args": ["public (default)\n  interfaces: eth0\ninternal\n  interfaces: eth1\n  sources: 192.168.50.0/24\ntrusted\n  sources: 10.8.0.0/16 fd00::/8\n", {}, "public", "eth1", "192.168.50.9"], "expected": "internal"}, {"args": ["public (default)\n  interfaces: eth0\ninternal\n  interfaces: eth1\n  sources: 192.168.50.0/24\ntrusted\n  sources: 10.8.0.0/16 fd00::/8\n", {}, "public", "eth0", "192.168.50.9"], "expected": "internal"}, {"args": ["public (default)\n  interfaces: eth0\ninternal\n  interfaces: eth1\n  sources: 192.168.50.0/24\ntrusted\n  sources: 10.8.0.0/16 fd00::/8\n", {}, "public", "eth0", "10.8.1.1"], "expected": "trusted"}, {"args": ["public (default)\n  interfaces: eth0\ninternal\n  interfaces: eth1\n  sources: 192.168.50.0/24\ntrusted\n  sources: 10.8.0.0/16 fd00::/8\n", {}, "public", "eth7", "8.8.4.4"], "expected": "public"}, {"args": ["public (default)\n  interfaces: eth0\ninternal\n  interfaces: eth1\n  sources: 192.168.50.0/24\ntrusted\n  sources: 10.8.0.0/16 fd00::/8\n", {}, "public", "eth0", "fd00::5"], "expected": "trusted"}, {"args": ["dmz\n  interfaces: eth1\nhome\n  sources: 192.168.0.0/16 aa:bb:cc:dd:ee:ff ipset:friends\nwork\n  sources: 192.168.1.0/24\npublic\n  interfaces: eth0\n", {}, "public", "eth1", "192.168.1.7"], "expected": "home"}, {"args": ["dmz\n  interfaces: eth1\nhome\n  sources: 192.168.0.0/16 aa:bb:cc:dd:ee:ff ipset:friends\nwork\n  sources: 192.168.1.0/24\npublic\n  interfaces: eth0\n", {"work": -1}, "public", "eth1", "192.168.1.7"], "expected": "work"}, {"args": ["dmz\n  interfaces: eth1\nhome\n  sources: 192.168.0.0/16 aa:bb:cc:dd:ee:ff ipset:friends\nwork\n  sources: 192.168.1.0/24\npublic\n  interfaces: eth0\n", {"public": -5}, "public", "eth0", "192.168.1.7"], "expected": "public"}, {"args": ["dmz\n  interfaces: eth1\nhome\n  sources: 192.168.0.0/16 aa:bb:cc:dd:ee:ff ipset:friends\nwork\n  sources: 192.168.1.0/24\npublic\n  interfaces: eth0\n", {}, "dmz", "eth9", "172.16.0.1"], "expected": "dmz"}, {"args": ["external\n  interfaces: ens3\ninternal\n  interfaces: ens4 ens5\nlibvirt\n  interfaces: virbr0\n  sources: 192.168.122.0/24\n", {}, "external", "ens3", "192.168.122.5"], "expected": "libvirt"}, {"args": ["external\n  interfaces: ens3\ninternal\n  interfaces: ens4 ens5\nlibvirt\n  interfaces: virbr0\n  sources: 192.168.122.0/24\n", {}, "external", "virbr0", "10.1.1.1"], "expected": "libvirt"}, {"args": ["public (default)\n  interfaces: eth0\n", {}, "public", "eth0", "1.2.3.4"], "expected": "public"}, {"args": ["", {}, "public", "eth0", "1.2.3.4"], "expected": "public"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 13, 'la13-shadowed', 8, 'func', 'Недостижимые правила', 'rules - список строк правил одной цепочки по порядку, как в листинге nft. Напишите функцию shadowed_rules(rules): верните список кортежей (i, j), номера с 1: правило i никогда не сработает, потому что раньше его перехватывает правило j (берите самое первое такое j) и пакет получает вердикт j. Правило j перехватывает правило i, когда оно завершающее и всё, что оно проверяет, шире или равно проверкам i. Завершающее правило - правило, где после условий и операторов counter (в том числе ''counter packets N bytes N''), log (в том числе с prefix "..." и level L) и comment "..." стоит accept, drop или reject, а после него ничего или только comment "..."; jump, goto, return и любые другие операторы (например limit) делают правило неизвестным: оно ничего не перехватывает и само не проверяется (в ответе не бывает). Правило с != или с неизвестным условием тоже неизвестное. Условия правила: ct state (множество), iif/iifname (множество строк), ip saddr и ip daddr (сети CIDR, адреса или список в фигурных скобках), ip protocol P и meta l4proto P (protocol), tcp dport и udp dport (множество портов, включая диапазоны a-b; они же задают protocol tcp/udp), icmp type T (протокол icmp и множество типов). Условие правила j шире или равно условию i, если для каждого поля из условия j: поле есть и у i, и множество i входит в множество j (для адресов - каждая сеть i лежит внутри одной сети j; для protocol - значения равны). Поле, которого нет у j, ничего не ограничивает.', 'def shadowed_rules(rules):
    pass
', 'Приведите каждое правило к словарю поле->множество (порты развернуть в set(range)). Для пары (j, i) проверьте включение по каждому полю j.', '{"func": "shadowed_rules", "tests": [{"args": [["ct state established,related accept", "ct state invalid drop", "iif \"lo\" accept", "tcp dport 22 accept", "tcp dport 22 ip saddr 10.0.0.0/8 accept", "tcp dport { 80, 443 } accept", "tcp dport 443 drop", "ip protocol icmp accept", "icmp type echo-request drop", "ct state established tcp dport 80 accept", "udp dport 53 ip saddr 192.168.0.0/16 accept", "udp dport 53 ip saddr 192.168.1.0/24 limit rate 10/second accept", "reject"]], "expected": [{"__tuple__": [5, 4]}, {"__tuple__": [7, 6]}, {"__tuple__": [9, 8]}, {"__tuple__": [10, 1]}]}, {"args": [["tcp dport 22 accept", "accept", "tcp dport 80 drop", "drop"]], "expected": [{"__tuple__": [3, 2]}, {"__tuple__": [4, 2]}]}, {"args": [["tcp dport 22 jump ssh", "tcp dport 22 accept"]], "expected": []}, {"args": [["ip saddr 10.0.0.0/8 counter packets 5 bytes 300 drop", "ip saddr 10.1.0.0/16 log prefix \"x\" accept"]], "expected": [{"__tuple__": [2, 1]}]}, {"args": [["iifname != \"lo\" drop", "iifname \"eth0\" drop"]], "expected": []}, {"args": [["tcp dport 53 accept", "udp dport 53 drop"]], "expected": []}, {"args": [["tcp dport 1000-2000 accept", "tcp dport 1500-1600 drop", "tcp dport 1900-2100 drop"]], "expected": [{"__tuple__": [2, 1]}]}, {"args": [["ip saddr { 10.0.0.0/8, 192.168.0.0/16 } accept", "ip saddr 192.168.4.0/24 accept", "ip saddr 172.16.0.0/12 accept"]], "expected": [{"__tuple__": [2, 1]}]}, {"args": [["iifname { \"eth0\", \"eth1\" } accept", "iifname \"eth1\" tcp dport 22 drop"]], "expected": [{"__tuple__": [2, 1]}]}, {"args": [["tcp dport 22 accept", "ct state new accept"]], "expected": []}, {"args": [["tcp dport 22 accept comment \"ssh\"", "tcp dport 22 drop"]], "expected": [{"__tuple__": [2, 1]}]}, {"args": [["ip daddr 192.0.2.10 accept", "ip daddr 192.0.2.10 tcp dport 80 reject", "ip daddr 192.0.2.0/24 reject"]], "expected": [{"__tuple__": [2, 1]}]}, {"args": [[]], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 13, 'la13-iptables-ports', 9, 'func', 'iptables-save в открытые порты', 'text - вывод iptables-save. Напишите функцию iptables_open_ports(text, src, iface): учитывается только таблица *filter и цепочка INPUT; верните словарь {''policy'': политика INPUT строчными буквами (''accept'', если строки :INPUT нет), ''tcp'': отсортированный список портов, ''udp'': то же}. В список протокола попадает порт, который упоминается в любом правиле как --dport P, --dport A:B (диапазон, включая A и B) или --dports P1,P2,A:B (multiport) и для которого НОВОЕ соединение от адреса src через интерфейс iface в цепочке INPUT получило бы ACCEPT. Правила проходятся по порядку; в правиле должны подойти все условия: -s сеть (адрес или CIDR), -i интерфейс, -p tcp|udp|icmp|all, --dport, --dports, -m conntrack --ctstate L и -m state --state L (список через запятую; подходит, если в нём есть NEW), а условия с ! перед -s или -i отрицаются. Модули -m tcp, -m udp, -m multiport, -m comment (с --comment "...") и -m state/-m conntrack только вводят свои опции. Цель после -j: ACCEPT, DROP, REJECT (с любыми опциями) заканчивают проверку, LOG не заканчивает (идём к следующему правилу), RETURN выходит из пользовательской цепочки назад, любое другое имя - пользовательская цепочка (переход как jump; если цепочка кончилась без вердикта, продолжаем после перехода). Если INPUT закончилась без вердикта, действует политика (ACCEPT или DROP).', 'def iptables_open_ports(text, src, iface):
    pass
', 'Соберите правила по цепочкам (-A ИМЯ), политики из строк '':ИМЯ ПОЛИТИКА'', кандидатов-портов из всех --dport/--dports; для каждого (протокол, порт) пройдите INPUT рекурсивно.', '{"func": "iptables_open_ports", "tests": [{"args": ["# Generated by iptables-save v1.8.10 (nf_tables) on Tue Nov  3 10:15:01 2026\n*filter\n:INPUT DROP [0:0]\n:FORWARD DROP [0:0]\n:OUTPUT ACCEPT [0:0]\n:SSH-IN - [0:0]\n-A INPUT -i lo -j ACCEPT\n-A INPUT -m conntrack --ctstate RELATED,ESTABLISHED -j ACCEPT\n-A INPUT -p tcp -m tcp --dport 22 -j SSH-IN\n-A INPUT -p tcp -m multiport --dports 80,443 -j ACCEPT\n-A INPUT -s 10.0.0.0/8 -p udp -m udp --dport 53 -j ACCEPT\n-A INPUT -p icmp -j ACCEPT\n-A SSH-IN -s 192.0.2.0/24 -j ACCEPT\n-A SSH-IN -j LOG --log-prefix \"ssh denied: \"\n-A SSH-IN -j RETURN\nCOMMIT\n# Completed on Tue Nov  3 10:15:01 2026\n", "192.0.2.5", "eth0"], "expected": {"policy": "drop", "tcp": [22, 80, 443], "udp": []}}, {"args": ["# Generated by iptables-save v1.8.10 (nf_tables) on Tue Nov  3 10:15:01 2026\n*filter\n:INPUT DROP [0:0]\n:FORWARD DROP [0:0]\n:OUTPUT ACCEPT [0:0]\n:SSH-IN - [0:0]\n-A INPUT -i lo -j ACCEPT\n-A INPUT -m conntrack --ctstate RELATED,ESTABLISHED -j ACCEPT\n-A INPUT -p tcp -m tcp --dport 22 -j SSH-IN\n-A INPUT -p tcp -m multiport --dports 80,443 -j ACCEPT\n-A INPUT -s 10.0.0.0/8 -p udp -m udp --dport 53 -j ACCEPT\n-A INPUT -p icmp -j ACCEPT\n-A SSH-IN -s 192.0.2.0/24 -j ACCEPT\n-A SSH-IN -j LOG --log-prefix \"ssh denied: \"\n-A SSH-IN -j RETURN\nCOMMIT\n# Completed on Tue Nov  3 10:15:01 2026\n", "10.3.3.3", "eth0"], "expected": {"policy": "drop", "tcp": [80, 443], "udp": [53]}}, {"args": ["# Generated by iptables-save v1.8.10 (nf_tables) on Tue Nov  3 11:00:00 2026\n*nat\n:PREROUTING ACCEPT [0:0]\n:INPUT ACCEPT [0:0]\n:OUTPUT ACCEPT [0:0]\n:POSTROUTING ACCEPT [0:0]\n-A PREROUTING -p tcp -m tcp --dport 8080 -j DNAT --to-destination 10.0.0.5:80\n-A POSTROUTING -o eth0 -j MASQUERADE\nCOMMIT\n*filter\n:INPUT ACCEPT [10:640]\n:FORWARD DROP [0:0]\n:OUTPUT ACCEPT [10:640]\n-A INPUT -p tcp -m tcp --dport 3306 -j REJECT --reject-with icmp-port-unreachable\n-A INPUT ! -s 192.0.2.0/24 -p tcp -m tcp --dport 5432 -j DROP\n-A INPUT -p tcp -m tcp --dport 8000:8003 -m comment --comment \"dev ports\" -j DROP\nCOMMIT\n", "203.0.113.9", "eth0"], "expected": {"policy": "accept", "tcp": [], "udp": [3306, 5432, 8000, 8001, 8002, 8003]}}, {"args": ["# Generated by iptables-save v1.8.10 (nf_tables) on Tue Nov  3 11:00:00 2026\n*nat\n:PREROUTING ACCEPT [0:0]\n:INPUT ACCEPT [0:0]\n:OUTPUT ACCEPT [0:0]\n:POSTROUTING ACCEPT [0:0]\n-A PREROUTING -p tcp -m tcp --dport 8080 -j DNAT --to-destination 10.0.0.5:80\n-A POSTROUTING -o eth0 -j MASQUERADE\nCOMMIT\n*filter\n:INPUT ACCEPT [10:640]\n:FORWARD DROP [0:0]\n:OUTPUT ACCEPT [10:640]\n-A INPUT -p tcp -m tcp --dport 3306 -j REJECT --reject-with icmp-port-unreachable\n-A INPUT ! -s 192.0.2.0/24 -p tcp -m tcp --dport 5432 -j DROP\n-A INPUT -p tcp -m tcp --dport 8000:8003 -m comment --comment \"dev ports\" -j DROP\nCOMMIT\n", "192.0.2.50", "eth0"], "expected": {"policy": "accept", "tcp": [5432], "udp": [3306, 5432, 8000, 8001, 8002, 8003]}}, {"args": ["*filter\n:INPUT DROP [0:0]\n:FORWARD DROP [0:0]\n:OUTPUT ACCEPT [0:0]\n-A INPUT -i eth1 -p tcp -m tcp --dport 22 -j ACCEPT\n-A INPUT -p tcp -m state --state NEW -m tcp --dport 80 -j ACCEPT\n-A INPUT -p tcp -m state --state ESTABLISHED -m tcp --dport 8080 -j ACCEPT\n-A INPUT -p udp -m udp --dport 1000:1002 -j ACCEPT\n-A INPUT -p udp -m udp --dport 123 -j LOG\nCOMMIT\n", "203.0.113.9", "eth0"], "expected": {"policy": "drop", "tcp": [80], "udp": [1000, 1001, 1002]}}, {"args": ["*filter\n:INPUT DROP [0:0]\n:FORWARD DROP [0:0]\n:OUTPUT ACCEPT [0:0]\n-A INPUT -i eth1 -p tcp -m tcp --dport 22 -j ACCEPT\n-A INPUT -p tcp -m state --state NEW -m tcp --dport 80 -j ACCEPT\n-A INPUT -p tcp -m state --state ESTABLISHED -m tcp --dport 8080 -j ACCEPT\n-A INPUT -p udp -m udp --dport 1000:1002 -j ACCEPT\n-A INPUT -p udp -m udp --dport 123 -j LOG\nCOMMIT\n", "203.0.113.9", "eth1"], "expected": {"policy": "drop", "tcp": [22, 80], "udp": [1000, 1001, 1002]}}, {"args": ["*filter\n:INPUT DROP [0:0]\n:FORWARD ACCEPT [0:0]\n:OUTPUT ACCEPT [0:0]\n:WEB - [0:0]\n:ADMIN - [0:0]\n-A INPUT -p tcp -m tcp --dport 80 -j WEB\n-A INPUT -p tcp -m tcp --dport 22 -j ADMIN\n-A INPUT -p tcp -m tcp --dport 22 -j ACCEPT\n-A WEB -s 203.0.113.0/24 -j DROP\n-A WEB -j ACCEPT\n-A ADMIN -s 198.51.100.0/24 -j RETURN\n-A ADMIN -j ACCEPT\nCOMMIT\n", "203.0.113.7", "eth0"], "expected": {"policy": "drop", "tcp": [22], "udp": []}}, {"args": ["*filter\n:INPUT DROP [0:0]\n:FORWARD ACCEPT [0:0]\n:OUTPUT ACCEPT [0:0]\n:WEB - [0:0]\n:ADMIN - [0:0]\n-A INPUT -p tcp -m tcp --dport 80 -j WEB\n-A INPUT -p tcp -m tcp --dport 22 -j ADMIN\n-A INPUT -p tcp -m tcp --dport 22 -j ACCEPT\n-A WEB -s 203.0.113.0/24 -j DROP\n-A WEB -j ACCEPT\n-A ADMIN -s 198.51.100.0/24 -j RETURN\n-A ADMIN -j ACCEPT\nCOMMIT\n", "198.51.100.7", "eth0"], "expected": {"policy": "drop", "tcp": [22, 80], "udp": []}}, {"args": ["", "1.2.3.4", "eth0"], "expected": {"policy": "accept", "tcp": [], "udp": []}}]}');
